"use strict";
// Main dashboard side of the pairing: gets each agent's token without the
// user ever seeing it (see lib/agent/agent-token.js for the agent side).
//
// The first call to an agent with no saved token pairs it: the address must
// first prove, without any token, that it is a Dashmon agent (/readyz), then
// POST /api/sync/pair hands back a token generated by the agent, saved in the
// token store. Agents of earlier versions, or set up with the shared
// DASHMON_SYNC_TOKEN, are paired by presenting that token: they switch to a
// token of their own on the way, with nothing to do.

const TOKEN_PATTERN = /^[A-Za-z0-9_-]{43}$/;

function failure(reason) {
  const error = new Error(`Agent pairing failed: ${reason}`);
  error.reason = reason;
  return error;
}

function createAgentPairing({
  store,
  request,
  timeout,
  fallbackToken = "",
  peers = () => [],
  log = { info() {}, warn() {} }
}) {
  const pending = new Map();
  // Agents older than the pairing, reached with the shared token: asked again
  // only after a refusal.
  const legacy = new Set();

  async function pair(url, presented) {
    try {
      const ready = await request(url, "/readyz", { timeout });
      if (ready?.role !== "agent") throw failure("not_agent");
    } catch (error) {
      throw error.reason ? error : failure("not_agent");
    }
    let payload;
    try {
      payload = await request(url, "/api/sync/pair", {
        method: "POST",
        timeout,
        headers: presented ? { "X-Dashmon-Sync-Token": presented } : {}
      });
    } catch (error) {
      if (error.status === 409) throw failure("already_paired");
      // An agent older than the pairing: it only knows the shared token.
      if (error.status === 404 && fallbackToken) {
        legacy.add(url);
        return fallbackToken;
      }
      throw failure(error.status === 404 ? "incompatible_protocol" : "unreachable");
    }
    const token = payload?.token;
    if (typeof token !== "string" || !TOKEN_PATTERN.test(token)) {
      throw failure("invalid_response");
    }
    store.set(url, token, peers());
    log.info(`Agent paired: ${url}`);
    return token;
  }

  // Concurrent calls (metrics collection, a test, a settings page) share one
  // pairing: a second one would be refused as "already paired".
  function pairOnce(url) {
    if (!pending.has(url)) {
      pending.set(
        url,
        pair(url, fallbackToken).finally(() => pending.delete(url))
      );
    }
    return pending.get(url);
  }

  function token(url) {
    const saved = store.get(url) || (legacy.has(url) ? fallbackToken : "");
    return saved ? Promise.resolve(saved) : pairOnce(url);
  }

  // Runs call(token) against the agent. A token refused (401) means the agent
  // was unpaired since (agent-token deleted, data volume recreated): it is
  // paired again, once.
  async function withToken(url, call) {
    const current = await token(url);
    try {
      return await call(current);
    } catch (error) {
      if (error.status !== 401) throw error;
      store.delete(url);
      legacy.delete(url);
      return call(await pairOnce(url));
    }
  }

  return { withToken, token };
}

module.exports = { createAgentPairing };
